// src/service/main/dialect/sqlServerDialects.ts
var u2 = class extends os {
  showVersion() {
    return "SELECT CAST(SERVERPROPERTY('ProductVersion') AS SYSNAME)+' '+CAST(SERVERPROPERTY('Edition') AS SYSNAME) AS server_version";
  }
  showAllForeignKeys() {
    return `SELECT 
    OBJECT_SCHEMA_NAME(fk.parent_object_id) AS table_schema,
    OBJECT_NAME(fk.parent_object_id) AS table_name,
    COL_NAME(fc.parent_object_id, fc.parent_column_id) AS column_name,
    OBJECT_SCHEMA_NAME(fk.referenced_object_id) AS referenced_schema,
    OBJECT_NAME(fk.referenced_object_id) AS referenced_table,
    COL_NAME(fc.referenced_object_id, fc.referenced_column_id) AS referenced_column
FROM 
    sys.foreign_keys fk
JOIN 
    sys.foreign_key_columns fc ON fk.object_id = fc.constraint_object_id`;
  }
  showAllComments() {
    return `SELECT 
        s.name table_schema,
        t.name AS table_name,
        c2.name AS column_name,
        prop.value AS comment
        FROM 
           sys.columns c2 
                join sys.tables t on c2.object_id=t.object_id
                join sys.schemas s on t.schema_id=s.schema_id 
                join sys.extended_properties prop ON prop.major_id = c2.object_id AND prop.minor_id = c2.column_id`;
  }
  createIndex(e) {
    return `ALTER TABLE ${e.table} ADD ${e.type} (${e.column})`;
  }
  dropIndex(e, t) {
    return `DROP INDEX ${e}.${t}`;
  }
  showIndex(e, t) {
    return `SELECT
        index_name = ind.name,
        column_name = col.name,
        ind.is_primary_key "isPrimary",
        ind.is_unique "isUnique",
        ind.is_unique_constraint,
        CASE 
            WHEN ind.is_primary_key=1 THEN 'PRIMARY'
            WHEN ind.is_unique=1 THEN 'UNIQUE'
            WHEN ind.is_unique_constraint=1 THEN 'UNIQUE'
        ELSE 'INDEX' END index_type
      FROM
        sys.indexes ind
        INNER JOIN sys.index_columns ic ON ind.object_id = ic.object_id
        and ind.index_id = ic.index_id
        INNER JOIN sys.columns col ON ic.object_id = col.object_id
        and ic.column_id = col.column_id
        INNER JOIN sys.tables t ON ind.object_id = t.object_id
      WHERE
        t.name = '${t}';`;
  }
  kill(e) {
    return `kill ${e.ID};`;
  }
  processList() {
    return `SELECT
    s.session_id "ID",
    s.login_name "User",
    s.program_name "Client",
    r.status "Status",
    r.wait_time "Wait Time",
    d.text "SQL"
FROM sys.dm_exec_sessions s
LEFT JOIN sys.dm_exec_requests r ON s.session_id = r.session_id
Outer APPLY sys.dm_exec_sql_text(sql_handle) d
WHERE s.is_user_process = 1;`;
  }
  addColumn(e, t) {
    return `ALTER TABLE ${e} 
    ADD $1 [type]$2;`;
  }
  /**
   * SQL Server有Login和User两种类型, 前者用于SQL Server身份验证, 后者用于数据库级别的User认证
   */
  createUser() {
    return `CREATE LOGIN loginName$1 WITH PASSWORD = 'password$2';
-- user master[YourDatabaseName]
CREATE USER userName$3 FOR LOGIN loginName$1;
ALTER ROLE db_datareader ADD MEMBER userName$3;
ALTER ROLE db_datawriter ADD MEMBER userName$3;
-- ALTER ROLE db_ddladmin ADD MEMBER userName$3;`;
  }
  updateColumn(e, t) {
    let { name: n, type: s, comment: o, nullable: a, defaultValue: c } = t, u = a == "YES" ? "NULL" : "NOT NULL";
    return `-- change column type
ALTER TABLE ${e} 
    ALTER COLUMN ${n} ${s} ${u};
-- change column name
EXEC sp_rename '${e}.${n}', '${n}', 'COLUMN';`;
  }
  /**
   * 以下属性不提供:
   * 1. 默认值是约束, 添加容易删除难
   * 2. 注释语法很复杂, 而且不是原生属性
   */
  updateColumnSql(e) {
    let { columnName: t, columnType: n, defaultValue: s, newColumnName: o, comment: a, oldRow: c, isNotNull: u, schema: l, table: f } = e, h = u ? "NOT NULL" : "NULL";
    return new lt(`ALTER TABLE "${l}"."${f}" ALTER COLUMN "${t}" ${n} ${h};`, `
`).if(c?.defaultValue && c.defaultValue != s, () => `DECLARE @constraintName NVARCHAR(128)
         SELECT @constraintName = dc.name
         FROM sys.default_constraints dc
         JOIN sys.columns c ON c.object_id = dc.parent_object_id AND c.column_id = dc.parent_column_id
         WHERE c.object_id = OBJECT_ID('${l}.${f}')
         AND c.name = '${t}';
         IF @constraintName IS NOT NULL
         BEGIN
             EXEC('ALTER TABLE "${l}"."${f}" DROP CONSTRAINT ' + @constraintName);
         END;`).if(!ac(s) && c.defaultValue != s, () => `ALTER TABLE "${l}"."${f}" ADD CONSTRAINT DF_${f}_${t} DEFAULT ${Aa(s, n)} FOR "${t}";`).if(t != o, () => `EXEC sp_rename '${l}.${f}.${t}' , '${o}', 'COLUMN';`).if(a != c.comment, () => `EXEC ${c.comment ? "sp_updateextendedproperty" : "sp_addextendedproperty"} 
@level0type = N'Schema', @level0name = '${l}',
@level1type = N'Table', @level1name = '${f}', 
@level2type = N'Column', @level2name = '${o}',
@name = N'MS_Description', @value = N'${a}';`).toString();
  }
  showDatabaseUsers() {
    return "SELECT name [user] from sys.database_principals WHERE type IN ('S', 'U', 'G','E') ";
  }
  updateTable(e) {
    let { schema: t, table: n, newTableName: s, comment: o, newComment: a } = e, c = "";
    return a && a != o && (c = `EXEC ${o ? "sp_updateextendedproperty" : "sp_addextendedproperty"} 
@level0type = N'Schema', @level0name = '${t}',
@level1type = N'Table', @level1name = '${n}', 
@name = N'MS_Description', @value = N'${a}';`), s && n != s && (c += `sp_rename '${n}', '${s}';`), c;
  }
  truncateDatabase(e) {
    return `SELECT Concat('TRUNCATE TABLE [',table_schema,'].[',TABLE_NAME, '];') trun FROM INFORMATION_SCHEMA.TABLES WHERE TABLE_TYPE = 'BASE TABLE'  AND TABLE_SCHEMA='${e}'`;
  }
  createDatabase(e) {
    return `create database ${e || "[name]"}`;
  }
  showViewSource(e, t) {
    return `SELECT definition 'Create View' FROM sys.sql_modules WHERE object_id = OBJECT_ID('${e}.${t}');`;
  }
  showProcedureSource(e, t) {
    return `SELECT definition 'Create Procedure','${e}.${t}' "Procedure" FROM sys.sql_modules WHERE object_id = OBJECT_ID('${e}.${t}');`;
  }
  showFunctionSource(e, t) {
    return `SELECT definition 'Create Function','${e}.${t}' "Function" FROM sys.sql_modules WHERE object_id = OBJECT_ID('${e}.${t}');`;
  }
  showTriggerSource(e, t) {
    return `SELECT definition 'SQL Original Statement','${e}.${t}' "Trigger" FROM sys.sql_modules WHERE object_id = OBJECT_ID('${e}.${t}');`;
  }
  /**
   * 之所以使用INFORMATION_SCHEMA.COLUMNS是因为内置表通常缺少名称, 类型和默认值.
   * remove extra、COLUMN_COMMENT(comment)、COLUMN_KEY(key)
   * SQLServer table column has primary and unique in same column, so it occur duplicate column.
   */
  showColumns(e, t) {
    return ["information_schema", "sys"].includes(e?.toLowerCase()) ? `SELECT
            name,
            type_name(system_type_id) "type",
            is_nullable nullable,
            max_length "maximum_length"
        FROM
            sys.all_columns
        WHERE
            object_id = OBJECT_ID('${e}.${t}') ;` : `SELECT 
               c.COLUMN_NAME "name",
               DATA_TYPE "type",
               numeric_precision "precision",
               numeric_scale "scale",
               IS_NULLABLE nullable, CHARACTER_MAXIMUM_LENGTH "maximum_length", COLUMN_DEFAULT "defaultValue", '' "comment", tc.constraint_type "key",
               COLUMNPROPERTY(object_id('${e}.${t}'), c.COLUMN_NAME, 'IsIdentity') extra
               FROM
               INFORMATION_SCHEMA.COLUMNS c
               left join  INFORMATION_SCHEMA.CONSTRAINT_COLUMN_USAGE ccu
               on c.COLUMN_NAME=ccu.column_name and c.table_name=ccu.table_name and ccu.TABLE_SCHEMA=c.TABLE_SCHEMA
               left join  INFORMATION_SCHEMA.TABLE_CONSTRAINTS tc
               on tc.constraint_name=ccu.constraint_name
               and tc.TABLE_SCHEMA=c.TABLE_SCHEMA and tc.table_name=c.table_name WHERE c.TABLE_SCHEMA = '${e}' AND c.table_name = '${t}' ORDER BY ORDINAL_POSITION`;
  }
  showChecks(e, t) {
    return `SELECT
        tc.CONSTRAINT_NAME "name",
        cc.CHECK_CLAUSE "clause"
    FROM
        "INFORMATION_SCHEMA"."CHECK_CONSTRAINTS" AS cc,
        "INFORMATION_SCHEMA"."TABLE_CONSTRAINTS" AS tc
    WHERE
        tc.CONSTRAINT_SCHEMA = '${e}'
        AND tc.TABLE_NAME = '${t}'
        AND tc.CONSTRAINT_TYPE = 'CHECK'
        AND tc.CONSTRAINT_SCHEMA = cc.CONSTRAINT_SCHEMA
        AND tc.CONSTRAINT_NAME = cc.CONSTRAINT_NAME;`;
  }
  showForeignKeys(e, t) {
    return `SELECT
        f.name AS "constraint_name",
        COL_NAME( fkc.parent_object_id, fkc.parent_column_id ) AS "column_name",
        OBJECT_NAME (fkc.referenced_object_id) AS "referenced_table",
        COL_NAME( fkc.referenced_object_id, fkc.referenced_column_id )  AS "referenced_column",
        update_referential_action_desc "updateRule",
        delete_referential_action_desc "deleteRule"
    FROM
        sys.foreign_key_columns fkc
        JOIN sys.foreign_keys f ON f.object_id = fkc.constraint_object_id
        JOIN sys.tables tab1 ON tab1.object_id = fkc.parent_object_id and tab1.name='${t}' and SCHEMA_NAME(tab1.schema_id)='${e}'
    ;`;
  }
  showTriggers(e, t) {
    let n = t ? ` AND tb.name='${t}'` : "";
    return `SELECT 
                tr.name AS trigger_name, 
                tb.name AS table_name,
                'Statement' AS orientation,
                OBJECT_DEFINITION(tr.object_id) AS source
            FROM 
                sys.triggers tr
                INNER JOIN sys.tables tb ON tr.parent_id = tb.object_id
                INNER JOIN sys.schemas sc ON tb.schema_id = sc.schema_id
            WHERE 
                tr.is_ms_shipped = 0
                AND sc.name = '${e}' ${n}`;
  }
  showProcedures(e) {
    return `SELECT ROUTINE_NAME FROM INFORMATION_SCHEMA.ROUTINES WHERE SPECIFIC_SCHEMA = '${e}' and ROUTINE_TYPE='PROCEDURE' ORDER BY ROUTINE_NAME`;
  }
  showFunctions(e) {
    return `SELECT ROUTINE_NAME FROM INFORMATION_SCHEMA.ROUTINES WHERE SPECIFIC_SCHEMA = '${e}' and ROUTINE_TYPE='FUNCTION' ORDER BY ROUTINE_NAME`;
  }
  showViews(e, t) {
    return `SELECT name FROM sys.all_views t where SCHEMA_NAME(t.schema_id)='${t}' order by name`;
  }
  buildPageSql(e, t, n) {
    return `SELECT TOP ${n} * FROM ${t};`;
  }
  showTables(e, t) {
    return `SELECT 
    t.name AS 'name', 
    ep.value AS 'comment', 
    t.is_ms_shipped AS 'isSystem',
    p.rows AS 'table_rows',
    SUM(a.total_pages) * 8 * 1024 AS 'data_length'
FROM 
    sys.tables t
    LEFT JOIN sys.extended_properties ep ON ep.major_id = t.object_id AND ep.minor_id = 0 AND ep.name = 'MS_Description'
    LEFT JOIN sys.indexes i ON t.object_id = i.object_id
    LEFT JOIN sys.partitions p ON i.object_id = p.object_id AND i.index_id = p.index_id
    LEFT JOIN sys.allocation_units a ON p.partition_id = a.container_id
WHERE
    t.schema_id = SCHEMA_ID('${t}')
GROUP BY 
    t.name, ep.value, t.is_ms_shipped, p.rows
ORDER BY 
    t.is_ms_shipped, t.name;`;
  }
  showDatabases() {
    return "SELECT name 'Database' FROM sys.databases";
  }
  showSchemas() {
    return "SELECT SCHEMA_NAME [schema] FROM INFORMATION_SCHEMA.SCHEMATA";
  }
  tableTemplate(e) {
    return `CREATE TABLE ${(e == "dbo" ? "" : `${e}.`) + "table_name"}$1(  
    id int IDENTITY(1,1) primary key,
    create_time DATETIME,
    update_time DATETIME,
    content$2 NVARCHAR(255)
);
EXECUTE sp_addextendedproperty N'MS_Description', '[table_comment]', N'user', N'dbo', N'table', N'[table_name]', NULL, NULL;
EXECUTE sp_addextendedproperty N'MS_Description', '[column_comment]', N'user', N'dbo', N'table', N'[table_name]', N'column', N'[column_name]';
`;
  }
  viewTemplate() {
    return `CREATE VIEW dbo.view_name$1
AS
SELECT * FROM 
`;
  }
  procedureTemplate() {
    return `CREATE PROCEDURE dbo.procedure_name$1
AS
BEGIN
    $2
END;`;
  }
  functionTemplate() {
    return `CREATE FUNCTION dbo.function_name$1() RETURNS [TYPE]
BEGIN
    $2
    return [value];
END;`;
  }
  triggerTemplate(e) {
    return `CREATE TRIGGER trigger_name$1
ON ${e ?? "[table_name]$2"}
[FOR/AFTER] INSERT
AS
BEGIN
    $3
END;`;
  }
  showRoles() {
    return "SELECT name FROM sys.server_principals WHERE type = 'R' ORDER BY name;";
  }
  showDatabaseRoles() {
    return "SELECT name FROM sys.database_principals WHERE type = 'R' ORDER BY name;";
  }
  createRole() {
    return `CREATE ROLE role_name$1;
-- Grant role privileges
GRANT role_name$1 TO role_name$2;`;
  }
  updateRole(e) {
    return `ALTER ROLE ${e} 
-- WITH NAME = new_name
;`;
  }
  grantRole(e) {
    return `ALTER ROLE ${e} ADD MEMBER role_name$1;`;
  }
  showLogins() {
    return `SELECT name as login, type_desc, is_disabled, create_date, modify_date 
        FROM sys.server_principals 
        WHERE type IN ('S', 'U', 'G','E') 
        ORDER BY name;`;
  }
  createLogin() {
    return `-- Create SQL Server login
CREATE LOGIN login_name$1 WITH PASSWORD = 'password$2';
-- Create Windows login
-- CREATE LOGIN [domainlogin_name$1] FROM WINDOWS;
-- Create login with additional options
-- CREATE LOGIN login_name$1 WITH PASSWORD = 'password$2', 
--     CHECK_POLICY = ON,
--     CHECK_EXPIRATION = ON,
--     DEFAULT_DATABASE = master,
--     DEFAULT_LANGUAGE = us_english;`;
  }
  updateLogin(e) {
    return `-- Change password
ALTER LOGIN ${e} WITH PASSWORD = 'new_password$1';
-- Disable/Enable login
-- ALTER LOGIN ${e} DISABLE;
-- ALTER LOGIN ${e} ENABLE;
-- Change default database
-- ALTER LOGIN ${e} WITH DEFAULT_DATABASE = database_name;
-- Change default language
-- ALTER LOGIN ${e} WITH DEFAULT_LANGUAGE = language;`;
  }
  dropLogin(e) {
    return `DROP LOGIN ${e};`;
  }
};

// src/service/main/dialect/nosql/neo4jDialect.ts
var l2 = class extends IS {
  showVersion() {
    return "call dbms.components() yield name, versions, edition unwind versions as server_version return server_version;";
  }
  showDatabases() {
    return "SHOW DATABASES yield name AS Database";
  }
  showSchemas() {
    return this.showDatabases();
  }
  showTables(e) {
    return "call db.labels() yield label as name RETURN name ORDER BY toLower(name)";
  }
  addColumn(e, t) {
    return `MATCH (n:${e}) WHERE id(n) = 1 SET n.name = 'name' RETURN n`;
  }
  showColumns(e, t) {
    return `MATCH(n:\`${t}\`) UNWIND keys(n) AS name RETURN DISTINCT name`;
  }
  showIndex(e, t) {
    return `show indexes yield name as index_name, properties as column_name, type as index_type, labelsOrTypes where '${t}' in labelsOrTypes`;
  }
  showViews(e) {
    return "call db.relationshipTypes() yield relationshipType AS name RETURN name ORDER BY toLower(name)";
  }
  showUsers() {
    return "SHOW USERS";
  }
  createUser() {
    return `CREATE USER [name] IF NOT EXISTS 
    SET PASSWORD 'password';`;
  }
  buildPageSql(e, t, n) {
    return `MATCH (n${t == "*" ? "" : `:${t}`}) RETURN n LIMIT ${n}`;
  }
  createDatabase(e) {
    return "CREATE DATABASE $1";
  }
  tableTemplate() {
    return "CREATE (n:node {id:1}) return n;";
  }
  createIndex(e) {
    return `CREATE INDEX FOR (n:${e.table}) ON (n.id)`;
  }
  dropIndex(e, t) {
    return `DROP INDEX \`${t}\``;
  }
  viewTemplate() {
    return "MATCH (n1:node {id:1}), (n2:node {id:2}) CREATE (n1)-[r:TO]->(n2) RETURN type(r)";
  }
};

// src/service/main/dialect/alter/postgreSQLAlterDialect.ts
var tE = class extends Id {
  /**
   * 注意: 在PG中自增就是修改默认值
   */
  defaultPart() {
    let { oldRow: e, isAutoIncrement: t, defaultValue: n, columnType: s } = this.param, o = n?.match?.(/\bnextval\b/);
    if (t && !e.isAutoIncrement && !o)
      return `${this.afterColumnPrefix} ADD GENERATED ALWAYS AS IDENTITY;`;
    if (!t && e.isAutoIncrement && !o)
      return `${this.afterColumnPrefix} DROP IDENTITY;`;
    if (!t && e.isAutoIncrement && o)
      return `${this.afterColumnPrefix} DROP DEFAULT;`;
    if (e.defaultValue == n) return "";
    let l = n?.match?.(/\bnextval\b/) ? n : Aa(n, s);
    return `${this.afterColumnPrefix} ${ac(n) ? "DROP DEFAULT" : `SET DEFAULT ${l}`};`;
  }
  commentPart() {
    let { oldRow: e, table: t, columnName: n, comment: s } = this.param;
    if (s != e.comment)
      return `COMMENT ON COLUMN "${t}"."${n}" is '${s}';`;
  }
};

// src/service/main/dialect/postgreSQLDialect.ts
var rE = class extends os {
  showVersion() {
    return "SHOW server_version;";
  }
  createIndex(e) {
    let t = e.name ?? `${e.column || "[column]"}`, n = e.indexType || "btree";
    return `CREATE INDEX ${t}_${(/* @__PURE__ */ new Date()).getTime()}_index ON 
    ${e.table} USING ${n} ("${e.column || "[column]"}");`;
  }
  dropIndex(e, t) {
    return `DROP INDEX "${t}"`;
  }
  showIndex(e, t) {
    return `select
    t.relname as table_name,
    i.relname as index_name,
    a.attname as column_name,
    ix.indisprimary "isPrimary",
    ix.indisunique "isUnique",
    CASE ix.indisprimary
        WHEN true THEN 'PRIMARY'
    ELSE CASE ix.indisunique
        WHEN true THEN 'UNIQUE'
    ELSE 'KEY'
    END
    END AS index_type,
    am.amname index_method,
    pg_get_indexdef(ix.indexrelid) as index_definition
  from
    pg_class t
    JOIN pg_catalog.pg_namespace pgn ON pgn.oid=t.relnamespace and pgn.nspname='${e}'
    JOIN pg_index ix on t.oid = ix.indrelid
    JOIN pg_class i on ix.indexrelid = i.oid
    JOIN pg_am am ON am.oid=i.relam
    LEFT JOIN pg_attribute a on t.oid = a.attrelid and a.attnum = ANY(ix.indkey)
  where
     t.relkind = 'r'
    and t.relname = '${t}'
  order by
    ix.indexrelid;`;
  }
  variableList() {
    return "SHOW ALL";
  }
  statusList() {
    return `SELECT
        'db_numbackends' AS db,
        pg_stat_get_db_numbackends(datid) AS status
      FROM
        pg_stat_database
      WHERE
        datname = current_database()
      UNION ALL
      SELECT
        'db_xact_commit',
        pg_stat_get_db_xact_commit(datid)
      FROM
        pg_stat_database
      WHERE
        datname = current_database()
      UNION ALL
      SELECT
        'db_xact_rollback',
        pg_stat_get_db_xact_rollback(datid)
      FROM
        pg_stat_database
      WHERE
        datname = current_database()
      UNION ALL
      SELECT
        'db_blocks_fetched',
        pg_stat_get_db_blocks_fetched(datid)
      FROM
        pg_stat_database
      WHERE
        datname = current_database()
      UNION ALL
      SELECT
        'db_blocks_hit',
        pg_stat_get_db_blocks_hit(datid)
      FROM
        pg_stat_database
      WHERE
        datname = current_database()`;
  }
  kill(e) {
    return `SELECT pg_terminate_backend(${e.ID})`;
  }
  processList() {
    return `SELECT
        a.pid AS "ID",
        query_start AS "Time",
        datname AS "db",
        CASE
        WHEN c.relname IS NOT NULL THEN c.relname
        ELSE l.virtualtransaction
        END AS "Target",
        l.mode AS "State",
        query AS "SQL"
      FROM
        pg_stat_activity a
        LEFT JOIN pg_locks l ON a.pid = l.pid
        LEFT JOIN pg_class c ON l.relation = c.oid
      ORDER BY
        a.pid ASC,
        c.relname ASC`;
  }
  addColumn(e, t) {
    return `ALTER TABLE ${e} 
  ADD COLUMN [column] [type];
COMMENT ON COLUMN ${e}.[column] IS 'comment';`;
  }
  createUser() {
    return `CREATE USER $1 WITH PASSWORD 'password$2';
-- Grant select privilege;
GRANT SELECT ON ALL TABLES IN SCHEMA public TO $1;
-- Grant all privileges;
GRANT ALL PRIVILEGES ON ALL TABLES IN SCHEMA public TO $1;`;
  }
  updateUser(e) {
    return `ALTER USER ${e} WITH PASSWORD 'new_password';`;
  }
  updateColumn(e, t) {
    let { name: n, type: s, comment: o, nullable: a, defaultValue: c } = t;
    return `-- change column type
ALTER TABLE ${e} 
    ALTER COLUMN ${n} TYPE ${s};
-- change column name
ALTER TABLE ${e} 
    RENAME COLUMN ${n} TO ${n};
-- Change column comment
COMMENT ON COLUMN ${e}.${n} IS '${o || "comment"}';`;
  }
  updateColumnSql(e) {
    return new tE(e).genAlterSQL();
  }
  showUsers() {
    return 'SELECT usename "user" from pg_user ';
  }
  showAllForeignKeys() {
    return `SELECT
    c.conname AS constraint_name,
    sch.nspname AS table_schema,
    tbl.relname AS table_name,
    (col.attname) as column_name,
    f_tbl.relname AS referenced_table,
    (f_col.attname) as referenced_column,
    c.confupdtype AS "updateRule",
    c.confdeltype AS "deleteRule"
FROM pg_constraint c
LEFT JOIN LATERAL UNNEST(c.conkey)
    WITH ORDINALITY AS u(attnum, attposition)
    ON TRUE
LEFT JOIN LATERAL UNNEST(c.confkey)
    WITH ORDINALITY AS f_u(attnum, attposition)
    ON f_u.attposition = u.attposition
JOIN pg_class tbl ON tbl.oid = c.conrelid
JOIN pg_namespace sch ON sch.oid = tbl.relnamespace
LEFT JOIN pg_attribute col
    ON (col.attrelid = tbl.oid AND col.attnum = u.attnum)
LEFT JOIN pg_class f_tbl ON f_tbl.oid = c.confrelid
LEFT JOIN pg_namespace f_sch ON f_sch.oid = f_tbl.relnamespace
LEFT JOIN pg_attribute f_col
    ON (f_col.attrelid = f_tbl.oid AND f_col.attnum = f_u.attnum)
WHERE c.contype = 'f'`;
  }
  showForeignKeys(e, t) {
    return `SELECT
    c.conname AS constraint_name,
    (col.attname) as column_name,
    f_tbl.relname AS referenced_table,
    (f_col.attname) as referenced_column,
    c.confupdtype AS "updateRule",
    c.confdeltype AS "deleteRule"
FROM pg_constraint c
LEFT JOIN LATERAL UNNEST(c.conkey) WITH ORDINALITY AS u(attnum, attposition) ON TRUE
LEFT JOIN LATERAL UNNEST(c.confkey) WITH ORDINALITY AS f_u(attnum, attposition) ON f_u.attposition = u.attposition
JOIN pg_class tbl ON tbl.oid = c.conrelid
JOIN pg_namespace sch ON sch.oid = tbl.relnamespace
LEFT JOIN pg_attribute col ON (col.attrelid = tbl.oid AND col.attnum = u.attnum)
LEFT JOIN pg_class f_tbl ON f_tbl.oid = c.confrelid
LEFT JOIN pg_namespace f_sch ON f_sch.oid = f_tbl.relnamespace
LEFT JOIN pg_attribute f_col ON (f_col.attrelid = f_tbl.oid AND f_col.attnum = f_u.attnum)
WHERE c.contype = 'f' and sch.nspname = '${e}' and tbl.relname = '${t}'`;
  }
  pingDataBase(e) {
    return e ? `set search_path to '${e}';` : null;
  }
  updateTable(e) {
    let { table: t, newTableName: n, comment: s, newComment: o } = e, a = "";
    return o && o != s && (a = `COMMENT ON TABLE "${t}" IS '${o}';`), n && t != n && (a += `ALTER TABLE "${t}" RENAME TO "${n}";`), a;
  }
  truncateDatabase(e) {
    return `SELECT Concat('TRUNCATE TABLE "',TABLE_NAME, '";') trun FROM INFORMATION_SCHEMA.TABLES WHERE  table_schema ='${e}' AND table_type='BASE TABLE';`;
  }
  createDatabase(e) {
    return "CREATE DATABASE $1";
  }
  showViewSource(e, t, n) {
    return `select pg_get_viewdef('${e}.${t}' :: regclass) "Create View"`;
  }
  showProcedureSource(e, t) {
    return `select pg_get_functiondef('${e}.${t}' :: regproc) "Create Procedure",'${t}' "Procedure";`;
  }
  showTriggerSource(e, t) {
    return `select pg_get_triggerdef(oid) "SQL Original Statement",'${e}.${t}' "Trigger" from pg_trigger where tgname = '${t}';`;
  }
  /**
   * key_column_usage: 记录创建外键约束的列(主动)
   * constraint_column_usage: 记录外键约束引用的列(被动)
   */
  showColumns(e, t, n) {
    return `SELECT 
          ${n ? "c.*," : ""}
          c.COLUMN_NAME "name", 
          atttypid::regtype AS pg_reg_type,
          DATA_TYPE "type",
          IS_NULLABLE nullable, 
          numeric_precision "precision",
          numeric_scale "scale",
          CHARACTER_MAXIMUM_LENGTH "maximum_length", 
          COLUMN_DEFAULT "defaultValue", 
          pg_catalog.col_description(pgc.oid, c.ordinal_position::int) AS "comment",
          tc.constraint_type "key",
          tc.constraint_name "constraint_name",
          cc.table_name "referenced_table",
          cc.column_name "referenced_column",
          pa.*
        FROM information_schema.columns c
        JOIN pg_catalog.pg_class pgc ON c.table_name = pgc.relname 
        JOIN pg_catalog.pg_namespace pgn ON pgn.oid=pgc.relnamespace and pgn.nspname=c.table_schema
        JOIN pg_attribute pa on pa.attname =c.column_name and pa.attrelid =pgc.oid 
        LEFT JOIN information_schema.key_column_usage ccu on ccu.table_schema=c.table_schema
          and ccu.table_name=c.table_name and ccu.column_name=c.COLUMN_NAME
        LEFT JOIN information_schema.table_constraints tc on tc.table_schema=c.table_schema 
          and tc.table_name=c.table_name and tc.constraint_name=ccu.constraint_name
        LEFT JOIN information_schema.constraint_column_usage cc on cc.table_schema=c.table_schema 
          and cc.constraint_name=tc.constraint_name and  tc.constraint_type='FOREIGN KEY'
        WHERE c.TABLE_SCHEMA = '${e}' AND c.table_name = '${t}' 
        ORDER BY c.ORDINAL_POSITION;`;
  }
  showChecks(e, t) {
    return `SELECT
    tc.CONSTRAINT_NAME "name",
    cc.CHECK_CLAUSE "clause"
FROM
    "information_schema"."check_constraints" AS cc,
    "information_schema"."table_constraints" AS tc
WHERE
    tc.CONSTRAINT_SCHEMA = '${e}'
    AND tc.TABLE_NAME = '${t}'
    AND tc.CONSTRAINT_TYPE = 'CHECK'
    AND tc.CONSTRAINT_SCHEMA = cc.CONSTRAINT_SCHEMA
    AND tc.CONSTRAINT_NAME = cc.CONSTRAINT_NAME
    AND cc.CONSTRAINT_NAME NOT LIKE '%_not_null'`;
  }
  /**
   * https://www.postgresql.org/docs/current/ddl-partitioning.html
   */
  showPartitions(e, t) {
    return `select col.column_name "columnName", pt.partition_strategy "strategy" from (
      select
          partrelid, partnatts, case partstrat when 'h' then 'HASH' when 'l' then 'LIST' when 'r' then 'RANGE' end as partition_strategy, unnest(partattrs) column_index
      from
          pg_partitioned_table ) pt
      join pg_class pc on pc.oid = pt.partrelid
      join information_schema.columns col on col.table_schema = pc.relnamespace :: regnamespace :: text
        and col.table_name = pc.relname and col.ordinal_position = pt.column_index
      WHERE col.table_schema='${e}' and col.table_name='${t}';`;
  }
  showTriggers(e, t) {
    let n = t ? ` AND event_object_table='${t}'` : "";
    return `SELECT 
              event_object_table table_name,
              trigger_name "trigger_name",
              action_timing timing,
              event_manipulation manipulation ,
              action_orientation orientation,
              action_statement "statement"
            FROM 
              information_schema.TRIGGERS 
            WHERE trigger_schema = '${e}' ${n} 
            ORDER BY TRIGGER_NAME ASC`;
  }
  /**
   * 本SQL只支持pg版本高11(2018年), 因为旧版本没有pg_proc.prokind字段
   */
  showProcedures(e) {
    return `SELECT p.proname "ROUTINE_NAME",
    pg_get_functiondef(p.oid) source,
    p.oid,
    pg_get_function_identity_arguments(p.oid) "argDefs"
from
    pg_proc p
    JOIN pg_namespace n ON p.pronamespace = n.oid
    and n.nspname = '${e}'
    and p.prokind = 'p'
order by p.proname`;
  }
  showFunctions(e) {
    return `SELECT DISTINCT
    r.ROUTINE_NAME AS "name",
    p.oid,
    pg_get_function_identity_arguments(p.oid) "argDefs",
    CASE 
        WHEN p.prorettype = 'pg_catalog.trigger'::regtype THEN 'Trigger'
        ELSE null
    END AS "function_type"
FROM 
    information_schema.routines r
    JOIN pg_proc p ON r.ROUTINE_NAME = p.proname 
    JOIN pg_namespace n ON p.pronamespace = n.oid 
    AND n.nspname = '${e}'
WHERE 
    r.ROUTINE_SCHEMA = '${e}' 
    AND r.ROUTINE_TYPE = 'FUNCTION' 
ORDER BY 
    r.ROUTINE_NAME ASC`;
  }
  showFunctionSource(e, t, n) {
    return n ? `select pg_get_functiondef('${n}') "Create Function",'${t}' "Function";` : `select pg_get_functiondef('${e}.${t}' :: regproc) "Create Function",'${t}' "Function";`;
  }
  showViews(e, t) {
    return `select table_name "name" from information_schema.tables where table_schema='${t}' and table_type='VIEW' order by "name";`;
  }
  showMaterialViews(e, t) {
    return `SELECT matviewname "name" from pg_matviews WHERE schemaname='${t}' order by "name" ASC`;
  }
  buildPageSql(e, t, n) {
    return `SELECT * FROM ${t} LIMIT ${n};`;
  }
  /**
   * pg的行数和数据量是定时统计的, 不准确
   */
  showTables(e, t) {
    return `SELECT t.table_name "name", 
    pg_catalog.obj_description(pgc.oid, 'pg_class') "comment",
    pgc.reltuples "table_rows",
    pg_total_relation_size(quote_ident(table_name)) AS "data_length"
FROM information_schema.tables t
JOIN pg_catalog.pg_class pgc ON t.table_name = pgc.relname 
JOIN pg_catalog.pg_namespace pgn ON pgn.oid=pgc.relnamespace and pgn.nspname=t.table_schema
WHERE t.table_type='BASE TABLE'
AND t.table_schema='${t}' order by t.table_name;`;
  }
  showDatabases() {
    return "SELECT datname FROM pg_database WHERE datistemplate = false order by datname ASC;";
  }
  showSchemas() {
    return 'SELECT nspname "schema" from pg_catalog.pg_namespace order by nspname ASC;';
  }
  showSequences(e) {
    return `SELECT sequencename AS name, 
                   last_value AS sequence, 
                   increment_by AS increment
            FROM pg_sequences 
            WHERE schemaname='${e}' 
            ORDER BY name;`;
  }
  showCustomTypes(e) {
    return `SELECT  t.typname as name,typtype as type,string_agg(pg_enum.enumlabel, ',') enum_values
    FROM        pg_type t 
    LEFT JOIN   pg_enum ON pg_enum.enumtypid = t.oid
    LEFT JOIN   pg_catalog.pg_namespace n ON n.oid = t.typnamespace 
    WHERE (t.typrelid = 0 OR (SELECT c.relkind = 'c' FROM pg_catalog.pg_class c WHERE c.oid = t.typrelid)) 
    AND     NOT EXISTS(SELECT 1 FROM pg_catalog.pg_type el WHERE el.oid = t.typelem AND el.typarray = t.oid)
    and n.nspname='${e}' GROUP BY name,type;`;
  }
  tableTemplate() {
    return `CREATE TABLE table_name$1(  
    id int NOT NULL PRIMARY KEY GENERATED ALWAYS AS IDENTITY,
    create_time DATE,
    name$2 VARCHAR(255)
);
COMMENT ON TABLE table_name$1 IS '$3';
COMMENT ON COLUMN table_name$1.name$2 IS '$4';`;
  }
  viewTemplate(e) {
    return `CREATE ${e ? "MATERIALIZED " : ""}VIEW view_name$1
AS
SELECT * FROM $2`;
  }
  procedureTemplate() {
    return `CREATE PROCEDURE proc_name$1()
LANGUAGE SQL
as $$
[$2]
$$;`;
  }
  triggerTemplate(e) {
    return `CREATE FUNCTION trigger_fun$1() RETURNS TRIGGER AS 
\\$body\\$
BEGIN
    $2
    RETURN [value];
END;
\\$body\\$ 
LANGUAGE plpgsql;

CREATE TRIGGER [name]$3
[BEFORE/AFTER] INSERT
ON ${e ?? "[table_name]$4"}
FOR EACH ROW
EXECUTE PROCEDURE [trigger_fun]();`;
  }
  dropTriggerTemplate(e, t) {
    return `DROP TRIGGER ${e} on ${t}`;
  }
  functionTemplate() {
    return `CREATE FUNCTION fun_name$1() 
RETURNS int$2 AS $$
BEGIN
    $3
    return 0;
END;
$$ LANGUAGE plpgsql;`;
  }
  showRoles() {
    return `SELECT rolname as name, rolsuper as is_superuser, rolcreaterole as can_create_role, 
            rolcreatedb as can_create_db, rolcanlogin as can_login, rolreplication as can_replicate
            FROM pg_roles ORDER BY rolname;`;
  }
  createRole() {
    return `CREATE ROLE role_name$1 WITH LOGIN PASSWORD 'password$2';
-- Grant role privileges
GRANT role_name$1 TO postgres;`;
  }
  updateRole(e) {
    return `ALTER ROLE ${e} WITH 
-- LOGIN/NOLOGIN
-- PASSWORD 'new_password'
-- SUPERUSER/NOSUPERUSER
-- CREATEDB/NOCREATEDB
-- CREATEROLE/NOCREATEROLE
-- INHERIT/NOINHERIT
-- REPLICATION/NOREPLICATION
-- BYPASSRLS/NOBYPASSRLS
-- CONNECTION LIMIT connlimit
-- VALID UNTIL 'timestamp'
;`;
  }
  grantRole(e) {
    return `GRANT ${e} TO role_name$1;`;
  }
};

// src/service/main/dialect/postgres/postgreCompatibleSQLDialect.ts
var Cd = class extends rE {
  showAllForeignKeys() {
    return `SELECT
      refc.constraint_name "constraint_name",
      refc.constraint_schema "table_schema",
      kcu.table_name "table_name",
      kcu.column_name AS "column_name",
      ccu.table_name AS "referenced_table",
      ccu.column_name AS "referenced_column"
  FROM
      information_schema.referential_constraints AS refc,
      information_schema.key_column_usage AS kcu,
      information_schema.constraint_column_usage AS ccu
  WHERE
      refc.constraint_name = kcu.constraint_name
      AND refc.constraint_schema = kcu.table_schema
      AND ccu.constraint_name = refc.constraint_name;`;
  }
  showForeignKeys(e, t) {
    return `SELECT
      refc.constraint_name "constraint_name",
      kcu.column_name AS column_name,
      ccu.table_name AS referenced_table,
      ccu.column_name AS referenced_column,
      kcu.ordinal_position AS ord_position,
      refc.update_rule "updateRule",
      refc.delete_rule "deleteRule"
  FROM
      information_schema.referential_constraints AS refc,
      information_schema.key_column_usage AS kcu,
      information_schema.constraint_column_usage AS ccu
  WHERE
      refc.constraint_schema = '${e}'
      AND refc.constraint_name = kcu.constraint_name
      AND refc.constraint_schema = kcu.table_schema
      AND ccu.constraint_name = refc.constraint_name
      AND kcu.table_name = '${t}'
  ORDER BY ord_position;`;
  }
  showProcedures(e) {
    return `SELECT ROUTINE_NAME "ROUTINE_NAME" FROM information_schema.routines WHERE ROUTINE_SCHEMA = '${e}' and ROUTINE_TYPE='PROCEDURE' ORDER BY ROUTINE_NAME ASC`;
  }
};

// src/service/main/dialect/postgres/redshiftSQLDialect.ts
var f2 = class extends Cd {
  showVersion() {
    return "SELECT VERSION() as server_version";
  }
  createIndex(e) {
    return null;
  }
  variableList() {
    return "SHOW ALL";
  }
  statusList() {
    return `SELECT
        'db_numbackends' AS db,
        pg_stat_get_db_numbackends(datid) AS status
      FROM
        pg_stat_database
      WHERE
        datname = current_database()
      UNION ALL
      SELECT
        'db_xact_commit',
        pg_stat_get_db_xact_commit(datid)
      FROM
        pg_stat_database
      WHERE
        datname = current_database()
      UNION ALL
      SELECT
        'db_xact_rollback',
        pg_stat_get_db_xact_rollback(datid)
      FROM
        pg_stat_database
      WHERE
        datname = current_database()
      UNION ALL
      SELECT
        'db_blocks_fetched',
        pg_stat_get_db_blocks_fetched(datid)
      FROM
        pg_stat_database
      WHERE
        datname = current_database()
      UNION ALL
      SELECT
        'db_blocks_hit',
        pg_stat_get_db_blocks_hit(datid)
      FROM
        pg_stat_database
      WHERE
        datname = current_database()`;
  }
  processList() {
    return `SELECT
        a.pid AS "Id",
        a.usename AS "User",
        a.client_addr AS "Host",
        a.client_port AS "Port",
        datname AS "db",
        query AS "Command",
        l.mode AS "State",
        query_start AS "Time",
        CASE
          WHEN c.relname IS NOT NULL THEN 'Locked Object: ' || c.relname
          ELSE 'Locked Transaction: ' || l.virtualtransaction
        END AS "Info"
      FROM
        pg_stat_activity a
        LEFT JOIN pg_locks l ON a.pid = l.pid
        LEFT JOIN pg_class c ON l.relation = c.oid
      ORDER BY
        a.pid ASC,
        c.relname ASC`;
  }
  addColumn(e, t) {
    return `ALTER TABLE ${e}
  ADD COLUMN [column] [type];
COMMENT ON COLUMN ${e}.[column] IS 'comment';`;
  }
  createUser() {
    return "CREATE USER [name] WITH PASSWORD 'password';";
  }
  updateUser(e) {
    return `ALTER USER ${e} WITH PASSWORD 'new_password';`;
  }
  updateColumn(e, t) {
    let { name: n, type: s } = t;
    return `-- change column type
ALTER TABLE ${e}
    ALTER COLUMN ${n} TYPE ${s};
-- change column name
ALTER TABLE ${e}
    RENAME COLUMN ${n} TO ${n};`;
  }
  /**
   * Redshift的自增为: "identity"(110415, 0, '1,1'::text), 但由于其不允许修改默认值, 所以目前没影响
   */
  updateColumnSql(e) {
    return new tE(e).genAlterSQL();
  }
  showUsers() {
    return 'SELECT usename "user" from pg_user ';
  }
  updateTable(e) {
    let { table: t, newTableName: n, comment: s, newComment: o } = e, a = "";
    return o && o != s && (a = `COMMENT ON TABLE "${t}" IS '${o}';`), n && t != n && (a += `ALTER TABLE "${t}" RENAME TO "${n}";`), a;
  }
  truncateDatabase(e) {
    return `SELECT Concat('TRUNCATE TABLE "',TABLE_NAME, '";') trun FROM INFORMATION_SCHEMA.TABLES WHERE  table_schema ='${e}' AND table_type='BASE TABLE';`;
  }
  createDatabase(e) {
    return "CREATE DATABASE $1";
  }
  showTableSource(e, t) {
    return `SHOW TABLE "${e}"."${t}"`;
  }
  showViewSource(e, t) {
    return `SHOW VIEW "${e}"."${t}"`;
  }
  showProcedureSource(e, t) {
    return `select pg_get_functiondef('${e}.${t}' :: regproc) "Create Procedure",'${t}' "Procedure";`;
  }
  showFunctionSource(e, t) {
    return `select pg_get_functiondef('${e}.${t}' :: regproc) "Create Function",'${t}' "Function";`;
  }
  showTriggerSource(e, t) {
    return `select pg_get_triggerdef(oid) "SQL Original Statement",'${e}.${t}' "Trigger" from pg_trigger where tgname = '${t}';`;
  }
  showPartitions(e, t) {
    return "";
  }
  showIndex(e, t) {
    return `select
    t.relname as table_name,
    i.relname as index_name,
    a.attname as column_name,
    ix.indisprimary "isPrimary",
    ix.indisunique "isUnique",
    CASE ix.indisprimary
        WHEN true THEN 'PRIMARY'
    ELSE CASE ix.indisunique
        WHEN true THEN 'UNIQUE'
    ELSE 'KEY'
    END
    END AS index_type,
    am.amname index_method
  from
    pg_class t
    join pg_catalog.pg_namespace pgn ON pgn.oid=t.relnamespace and pgn.nspname='${e}'
    join pg_index ix on t.oid = ix.indrelid
    join pg_class i on ix.indexrelid = i.oid
    JOIN pg_am am ON am.oid=i.relam
    LEFT JOIN pg_attribute a on t.oid = a.attrelid and a.attnum = ANY(string_to_array(textin(int2vectorout(ix.indkey)),' ')::int[])
  where
     t.relkind = 'r'
    and t.relname = '${t}'
  order by
    ix.indexrelid;`;
  }
  showSequences(e) {
    return `SELECT sequence_name name FROM information_schema.sequences WHERE sequence_schema = '${e}' ORDER BY sequence_name`;
  }
  showTriggers(e, t) {
    let n = t ? ` AND event_object_table='${t}'` : "";
    return `SELECT TRIGGER_NAME "trigger_name" FROM information_schema.TRIGGERS WHERE trigger_schema = '${e}' ${n} ORDER BY TRIGGER_NAME ASC`;
  }
  showProcedures(e) {
    return `SELECT ROUTINE_NAME "ROUTINE_NAME" FROM information_schema.routines WHERE ROUTINE_SCHEMA = '${e}' and ROUTINE_TYPE='PROCEDURE' ORDER BY ROUTINE_NAME ASC`;
  }
  showFunctions(e) {
    return `SELECT ROUTINE_NAME "ROUTINE_NAME" FROM information_schema.routines WHERE ROUTINE_SCHEMA = '${e}' and ROUTINE_TYPE='FUNCTION' ORDER BY ROUTINE_NAME ASC `;
  }
  showTables(e, t) {
    return `  SELECT t.table_name "name", pg_catalog.obj_description(pgc.oid, 'pg_class') "comment",
    pg_total_relation_size(quote_ident(table_name)) AS "data_length"
FROM information_schema.tables t
JOIN pg_catalog.pg_class pgc ON t.table_name = pgc.relname
JOIN pg_catalog.pg_namespace pgn ON pgn.oid=pgc.relnamespace and pgn.nspname=t.table_schema
WHERE t.table_type='BASE TABLE'
AND t.table_schema='${t}' order by t.table_name;`;
  }
  showSchemas() {
    return 'SELECT nspname "schema" from pg_catalog.pg_namespace order by nspname ASC;';
  }
  tableTemplate() {
    return `CREATE TABLE table_name$1(
    id INT identity(1, 1) NOT NULL PRIMARY KEY,
    create_time DATE,
    update_time DATE,
    content$2 VARCHAR(255)
);
COMMENT ON TABLE table_name IS 'table_comment';
COMMENT ON COLUMN table_name.content IS 'content';`;
  }
  procedureTemplate() {
    return `CREATE PROCEDURE procedure_name()
as $$
begin
    SELECT 1;
END;
$$ LANGUAGE plpgsql;`;
  }
  functionTemplate() {
    return `CREATE FUNCTION function_name()
RETURNS int STABLE
AS $$
    SELECT 1
$$ LANGUAGE sql;`;
  }
};

// src/service/main/dialect/snowflakeDialect.ts
var d2 = class extends os {
  showVersion() {
    return 'select CURRENT_VERSION() as "server_version";';
  }
  createIndex(e) {
    let t = `${e.type || "key"}`;
    return t.match(/BTREE/i) && (t = "key"), `ALTER TABLE ${e.table} ADD ${t} (\`${e.column || "$1"}\`)`;
  }
  dropIndex(e, t) {
    return `ALTER TABLE ${e} DROP INDEX \`${t}\``;
  }
  // mysql8大小写区分
  showIndex(e, t) {
    return "";
  }
  addColumn(e, t) {
    let n = t ? ` AFTER \`${t}\`` : "";
    return `ALTER TABLE ${e} 
    ADD COLUMN $1 [type]$2 COMMENT '$3'${n};`;
  }
  createUser() {
    return `CREATE USER '$1'@'%' IDENTIFIED BY 'password$2';
-- Grant select privilege to all databases;
GRANT SELECT ON *.* TO '$1'@'%' WITH GRANT OPTION;
-- Grant all privileges to all databases;
GRANT ALL PRIVILEGES ON *.* TO '$1'@'%' WITH GRANT OPTION;`;
  }
  updateColumn(e, t) {
    let { name: n, type: s, comment: o, nullable: a, defaultValue: c, extra: u, character_set_name: l, collation_name: f } = t, h = a != "YES";
    return new lt(`ALTER TABLE ${e}`).append(`
	CHANGE ${n} ${n} ${s}`).if(l, `CHARACTER SET ${l}`).if(f, `COLLATE ${f}`).if(h, "NOT NULL").if(u?.toLowerCase()?.includes("auto_increment"), "AUTO_INCREMENT").if(o, `COMMENT '${o}'`).if(ac(c) && !h, "DEFAULT NULL").if(!ac(c), `DEFAULT ${c == "CURRENT_TIMESTAMP" ? c : `'${ep(c)}'`}`).toString();
  }
  /**
   * https://docs.snowflake.com/en/sql-reference/sql/alter-table-column#syntax
   */
  updateColumnSql(e) {
    let {
      table: t,
      columnName: n,
      newColumnName: s,
      columnType: o,
      isNotNull: a,
      isAutoIncrement: c,
      comment: u,
      defaultValue: l,
      oldRow: f
    } = e, h = `ALTER TABLE "${t}"`, p = a ? "SET NOT NULL" : "DROP NOT NULL";
    return new lt(`${h} ALTER COLUMN "${n}" TYPE ${o};`, `
`).if(u && u != f.comment, `${h} ALTER COLUMN "${n}" COMMENT '${u}';`).if(a != f.isNotNull, `${h} ALTER COLUMN "${n}" ${p};`).if(n != s, `${h} RENAME COLUMN "${n}" TO "${s}";`).toString();
  }
  showCollations() {
    return "";
  }
  showChecks(e, t) {
    return "";
  }
  pingDataBase(e, t) {
    return e ? `use "${t}"."${e}"` : "select 1";
  }
  updateTable(e) {
    let { table: t, newTableName: n, comment: s, newComment: o, collation: a, newCollation: c } = e, u = "";
    return o && o != s && (u = `ALTER TABLE \`${t}\` COMMENT = '${o}';`), c && c != a && (u += `ALTER TABLE \`${t}\` collate = '${c}';`), n && t != n && (u += `ALTER TABLE \`${t}\` RENAME TO \`${n}\`;`), u;
  }
  truncateDatabase(e) {
    return `SELECT Concat('TRUNCATE TABLE \`',table_schema,'\`.\`',TABLE_NAME, '\`;') trun FROM INFORMATION_SCHEMA.TABLES where  table_schema ='${e}' and TABLE_TYPE<>'VIEW';`;
  }
  createDatabase(e) {
    return "CREATE DATABASE $1;";
  }
  showTableSource(e, t) {
    return `select get_ddl('table', '${e}.${t}') "Create Table";`;
  }
  showViewSource(e, t) {
    return `select get_ddl('view', '${e}.${t}') "Create View";`;
  }
  showProcedureSource(e, t) {
    return `select get_ddl('PROCEDURE', '${e}.${t}()') "Create Procedure";`;
  }
  showFunctionSource(e, t) {
    return `select get_ddl('FUNCTION', '${e}.${t}()') "Create Function";`;
  }
  showColumns(e, t) {
    return `SELECT 
        c.COLUMN_NAME "name",
        DATA_TYPE "type",
        CHARACTER_MAXIMUM_LENGTH "maximum_length",
        IS_IDENTITY "key",
        COMMENT "comment",
        IS_NULLABLE "nullable",
        COLUMN_DEFAULT "defaultValue",
        COLLATION_NAME "$"
        FROM information_schema.columns c
        WHERE c.table_schema = '${e}' AND c.table_name = '${t}' 
        ORDER BY c.ORDINAL_POSITION;`;
  }
  showProcedures(e) {
    return `SELECT PROCEDURE_NAME ROUTINE_NAME FROM information_schema.PROCEDURES WHERE PROCEDURE_SCHEMA = '${e}' ORDER BY PROCEDURE_NAME`;
  }
  showFunctions(e) {
    return `SELECT FUNCTION_NAME ROUTINE_NAME FROM INFORMATION_SCHEMA.FUNCTIONS WHERE FUNCTION_SCHEMA='${e}' ORDER BY FUNCTION_NAME`;
  }
  showViews(e, t) {
    return `SELECT COMMENT "comment",TABLE_NAME "name",ROW_COUNT "table_rows"
        FROM information_schema.TABLES  WHERE TABLE_SCHEMA = '${t}' and TABLE_TYPE='VIEW' ORDER BY TABLE_NAME;`;
  }
  buildPageSql(e, t, n) {
    return `SELECT * FROM ${t} LIMIT ${n};`;
  }
  showTables(e, t) {
    return `SELECT COMMENT "comment",TABLE_NAME "name",ROW_COUNT "table_rows"
        FROM information_schema.TABLES  WHERE TABLE_SCHEMA = '${t}' and TABLE_TYPE<>'VIEW' ORDER BY TABLE_NAME;`;
  }
  showDatabases() {
    return "show databases;";
  }
  showSchemas() {
    return 'SELECT SCHEMA_NAME "schema" FROM INFORMATION_SCHEMA.SCHEMATA;';
  }
  tableTemplate() {
    return `CREATE TABLE table_name$1(  
    id int NOT NULL PRIMARY KEY AUTOINCREMENT,
    create_time DATE,
    name$2 VARCHAR(255)
);
COMMENT ON TABLE table_name$1 IS '$3';
COMMENT ON COLUMN table_name$1.name$2 IS '$4';`;
  }
  viewTemplate() {
    return `CREATE VIEW view_name$1
AS
SELECT * FROM $2`;
  }
  procedureTemplate() {
    return `create procedure proc_name$1() returns string
language javascript
as $$
    $2return 1+1;
$$;`;
  }
  functionTemplate() {
    return `CREATE FUNCTION fun_name$1() RETURNS int
AS
$$
    $2return 1;
$$`;
  }
  showRoles() {
    return "SELECT ROLE_NAME FROM information_schema.applicable_roles ORDER BY ROLE_NAME;";
  }
  createRole() {
    return `CREATE ROLE role_name$1;
-- Grant role privileges
GRANT ROLE role_name$1 TO role role_name$2;`;
  }
  updateRole(e) {
    return `ALTER ROLE ${e} 
-- RENAME TO new_name
;`;
  }
  grantRole(e) {
    return `GRANT ROLE ${e} TO ROLE role_name$1;`;
  }
};

// src/service/main/dialect/sqliteDialect.ts
var nE = class extends os {
  showDatabases() {
    return null;
  }
  showSchemas(e) {
    return null;
  }
  createDatabase(e) {
    return null;
  }
  updateTable(e) {
    let { table: t, newTableName: n } = e, s = "";
    return n && t != n && (s += `ALTER TABLE ${t} RENAME TO ${n};`), s;
  }
  showVersion() {
    return "select sqlite_version() as server_version";
  }
  updateColumn(e, t) {
    return null;
  }
  updateColumnSql(e) {
    return null;
  }
  createIndex(e) {
    let { table: t, column: n = "$2" } = e;
    return `CREATE INDEX ${`${t}_${n}`} ON ${t}(${n});`;
  }
  showIndex(e, t) {
    return `SELECT name index_name FROM sqlite_master WHERE type='index' and tbl_name='${t}' `;
  }
  dropIndex(e, t) {
    return `DROP INDEX ${t};`;
  }
  showTables(e, t) {
    return "SELECT name, type FROM sqlite_master WHERE type='table' ORDER BY type ASC, name ASC;";
  }
  addColumn(e, t) {
    return `ALTER TABLE ${e} 
    ADD COLUMN $1 [type$2];`;
  }
  showSequences(e) {
    return "SELECT name,seq sequence FROM sqlite_sequence";
  }
  showColumns(e, t) {
    return `SELECT t1.*,t1.pk "key",t1.dflt_value "defaultValue",t2."table" "referenced_table",t2."to" "referenced_column" FROM PRAGMA_TABLE_INFO('${t}') t1
        left join (
            SELECT * FROM  pragma_foreign_key_list('${t}')
        ) t2  on t1.name=t2.'from';`;
  }
  showViews(e, t) {
    return "SELECT name, type FROM sqlite_master WHERE type='view' AND name <> 'sqlite_sequence' AND name <> 'sqlite_stat1' ORDER BY type ASC, name ASC;";
  }
  showTriggers(e, t) {
    return `SELECT name, tbl_name, sql FROM sqlite_master WHERE type='trigger' ${t ? ` AND tbl_name='${t}'` : ""} ORDER BY name ASC;`;
  }
  buildPageSql(e, t, n) {
    return `SELECT * FROM ${t} LIMIT ${n};`;
  }
  showTableSource(e, t) {
    return `SELECT sql "Create Table" FROM sqlite_master where name='${t}' and type='table';`;
  }
  showViewSource(e, t) {
    return `SELECT sql "Create View" FROM sqlite_master where name='${t}' and type='view';`;
  }
  showTriggerSource(e, t) {
    return `SELECT sql FROM sqlite_master where name='${t}' and type='trigger';`;
  }
  tableTemplate() {
    return `CREATE TABLE table_name$1(  
    id INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT,
    content TEXT
);`;
  }
  viewTemplate() {
    return `CREATE VIEW view_name$1
AS
SELECT * FROM $2`;
  }
};

// src/service/main/dialect/duckdbDialect.ts
var h2 = class extends nE {
  showVersion() {
    return "SELECT library_version as server_version from pragma_version()";
  }
  pingDataBase(e, t) {
    return e ? `set schema '${e}';` : null;
  }
  showDatabases() {
    return 'SELECT DISTINCT catalog_name "Database" from information_schema.schemata ORDER BY catalog_name';
  }
  showSchemas(e) {
    return `SELECT schema_name "schema" from information_schema.schemata WHERE catalog_name='${e}' ORDER BY schema_name`;
  }
  showTables(e, t) {
    return `SELECT table_name "name" FROM information_schema.tables
        WHERE table_type in ('BASE TABLE','LOCAL TEMPORARY') and table_catalog='${e}' and table_schema = '${t}' order by table_name`;
  }
  showViews(e, t) {
    return `
SELECT table_name "name",1 "view_group",null "source" FROM information_schema.tables
        WHERE table_type='VIEW' and table_catalog='${e}' and table_schema = '${t}'
        UNION all
SELECT viewname "name",2 "view_group",definition "source" FROM pg_catalog.pg_views
        WHERE schemaname = '${t}'
ORDER BY "view_group",name`;
  }
  showSequences(e) {
    return `SELECT sequence_name AS name, last_value AS sequence 
                FROM duckdb_sequences() 
                WHERE schema_name = '${e}'`;
  }
  tableTemplate() {
    return `CREATE TABLE table_name$1(  
    id INTEGER NOT NULL PRIMARY KEY,
    content TEXT
);`;
  }
  showColumns(e, t) {
    return ["system", "temp"].includes(e) ? `SELECT column_name "name", data_type "type",
        column_default "defaultValue", is_nullable "nullable"
        FROM information_schema.columns c
        WHERE c.table_schema = '${e}' AND c.table_name = '${t}' 
        ORDER BY c.ORDINAL_POSITION;` : `SELECT t1.*,t1.pk "key",t1.dflt_value "defaultValue" FROM PRAGMA_TABLE_INFO('${t}') t1;`;
  }
  updateColumn(e, t) {
    let { name: n, type: s } = t;
    return `-- change column type
ALTER TABLE ${e} 
    ALTER COLUMN ${n} TYPE ${s};
-- change column name
ALTER TABLE ${e} 
    RENAME COLUMN ${n} TO ${n};`;
  }
  updateColumnSql(e) {
    return new Id(e).genAlterSQL();
  }
};

// src/service/main/dialect/sql-other/hiveDialect.ts
var CS = class extends Lo {
  showVersion() {
    return "select version() as server_version;";
  }
  showDatabases() {
    return "show databases";
  }
  showTables(e, t) {
    return `show tables in ${e}`;
  }
  showColumns(e, t) {
    return `describe ${e}.${t};`;
  }
  showViews(e, t) {
    return `show views in ${e}`;
  }
};

// src/service/main/dialect/sql-other/prestoDialect.ts
var p2 = class extends Lo {
  showVersion() {
    return "SELECT node_version as server_version FROM system.runtime.nodes;";
  }
  pingDataBase(e) {
    return e ? `use ${e}` : null;
  }
  showDatabases() {
    return "show catalogs";
  }
};

// src/service/main/dialect/sql-other/cassandraDialect.ts
var m2 = class extends Lo {
  showVersion() {
    return "select release_version from system.local;";
  }
  showUsers() {
    return 'SELECT role as "user" FROM system_auth.roles;';
  }
  pingDataBase(e) {
    return e ? `use ${e}` : null;
  }
  createDatabase(e) {
    return `CREATE KEYSPACE $1
WITH REPLICATION = { 
    'class' : 'SimpleStrategy', 
    'replication_factor' : 1 
};`;
  }
  dropDatabase(e) {
    return `DROP KEYSPACE ${e}`;
  }
  showDatabases() {
    return 'select keyspace_name as "database" from system_schema.keyspaces;';
  }
  showTables(e, t) {
    return `select table_name as "name" from system_schema.tables where keyspace_name='${e}'`;
  }
  showColumns(e, t) {
    return `select column_name as "name", type, kind as "key" 
                from system_schema.columns 
                where keyspace_name='${e}' 
                and table_name='${t}'`;
  }
  tableTemplate() {
    return `CREATE TABLE table_name$1(  
    id int PRIMARY key,
    create_time DATE,
    update_time DATE,
    content TEXT
);`;
  }
};

// src/service/main/dialect/alter/db2AlterDialect.ts
var E2 = class extends Id {
  otherPart() {
    let { oldRow: e, isAutoIncrement: t } = this.param;
    return !e.isAutoIncrement && t ? `${this.afterColumnPrefix} SET GENERATED ALWAYS as identity;` : e.isAutoIncrement && !t ? `${this.afterColumnPrefix} DROP GENERATED;` : null;
  }
  commentPart() {
    let { oldRow: e, table: t, columnName: n, comment: s } = this.param;
    if (s != e.comment)
      return `COMMENT ON COLUMN "${t}"."${n}" is '${s}';`;
  }
  changeTypePart() {
    let { oldRow: e, columnType: t } = this.param;
    return e.type == t ? "" : `${this.afterColumnPrefix} SET DATA TYPE ${t};`;
  }
};

// src/service/main/dialect/sql-other/db2Dialect.ts
var wS = class extends Lo {
  showVersion() {
    return 'SELECT SERVICE_LEVEL as "server_version" FROM SYSIBMADM.ENV_INST_INFO;';
  }
  showUsers() {
    return `SELECT GRANTEE "user" FROM syscat.dbauth WHERE GRANTEETYPE='U';`;
  }
  pingDataBase(e) {
    return e ? `set SCHEMA ${e}` : null;
  }
  showDatabases() {
    return 'select schemaname "database" from syscat.schemata';
  }
  showTableSource(e, t) {
    return null;
  }
  showTables(e, t) {
    return `select tabname "name", remarks "comment" from syscat.tables where tabschema='${t}' and TYPE='T' order by tabname`;
  }
  showColumns(e, t) {
    return `select COLUMN_NAME "name",
        DATA_TYPE "type",
        IS_NULLABLE "nullable",
        NUMERIC_PRECISION "precision",
        NUMERIC_SCALE "scale",
        CHARACTER_MAXIMUM_LENGTH "maximum_length",
        sc.length "number_length",
        COLUMN_DEFAULT "defaultValue",
        tc.TYPE "key",
        sc.remarks "comment",
        sc.IDENTITY "extra",
        r.REFTABNAME "referenced_table",
        trim(r.PK_COLNAMES) "referenced_column"
        from SYSIBM.columns c
        left join syscat.keycoluse kc
            on c.TABLE_SCHEMA=kc.TABSCHEMA and c.TABLE_NAME=kc.TABNAME  and c.COLUMN_NAME=kc.COLNAME
        left join SYSCAT.tabconst tc
            on c.TABLE_SCHEMA=tc.TABSCHEMA and c.TABLE_NAME=tc.TABNAME  and tc.CONSTNAME=kc.CONSTNAME
        left join sysibm.syscolumns sc
            on c.TABLE_SCHEMA=sc.TBCREATOR and c.TABLE_NAME=sc.TBNAME  and c.COLUMN_NAME=sc.NAME
        left join syscat.references r
            on c.TABLE_SCHEMA=r.TABSCHEMA and c.TABLE_NAME=r.TABNAME  and c.COLUMN_NAME=trim(r.FK_COLNAMES)
        where
            TABLE_SCHEMA = '${e}'
            and TABLE_NAME = '${t}'
        order by ORDINAL_POSITION;`;
  }
  updateColumnSql(e) {
    return new E2(e).genAlterSQL();
  }
  showAllForeignKeys() {
    return `SELECT 
        CONSTNAME "constraint_name",
        TABSCHEMA "table_schema",
        TABNAME "table_name",
        FK_COLNAMES "column_name",
    REFTABNAME "referenced_table",
    PK_COLNAMES "referenced_column"
     FROM syscat.references`;
  }
  showForeignKeys(e, t) {
    return `SELECT 
        FK_COLNAMES "column_name",
        CONSTNAME "constraint_name",
        REFTABNAME "referenced_table",
        PK_COLNAMES "referenced_column",
        UPDATERULE "updateRule",
        DELETERULE "deleteRule"
         FROM syscat.references WHERE 
        TABSCHEMA='${e}' and TABNAME='${t}'`;
  }
  showIndex(e, t) {
    return `SELECT 
        COLNAMES "column_name",
        INDNAME "index_name",
        UNIQUERULE='U' "isUnique"
         FROM SYSCAT.INDEXES WHERE TABNAME = '${t}' AND TABSCHEMA = '${e}'`;
  }
  showViews(e, t) {
    return `select VIEWNAME "name",TEXT "source" from SYSCAT.VIEWS where VIEWSCHEMA = '${t}';`;
  }
  showProcedures(e) {
    return `select PROCNAME "routine_name",TEXT "source" from SYSCAT.procedures where PROCSCHEMA = '${e}' order by PROCNAME;`;
  }
  showChecks(e, t) {
    return `SELECT CONSTNAME "name",TEXT "clause" FROM SYSCAT.CHECKS WHERE TABNAME = '${t}' AND TABSCHEMA = '${e}';`;
  }
  showTriggers(e, t) {
    let n = `SELECT TRIGNAME "trigger_name",TEXT "source",TABNAME "table_name",TRIGEVENT "event" FROM syscat.triggers WHERE TABSCHEMA = '${e}'`;
    return t && (n += `AND TABNAME = '${t}'`), n;
  }
  showFunctions(e) {
    return `select FUNCNAME "routine_name",BODY "source" from SYSCAT.FUNCTIONS where FUNCSCHEMA = '${e}' order by FUNCNAME;`;
  }
  dropIndex(e, t) {
    return `DROP INDEX "${t}"`;
  }
  createDatabase(e) {
    return `CREATE SCHEMA ${e}$1;`;
  }
  tableTemplate() {
    return `CREATE TABLE table_name$1(  
    id INTEGER NOT NULL PRIMARY KEY GENERATED ALWAYS AS IDENTITY,
    create_time DATE,
    update_time DATE,
    content VARCHAR(255)
);`;
  }
  processList() {
    return `SELECT session_auth_id,
        application_handle,
        elapsed_time_sec,
        activity_state,
        rows_read,
        stmt_text info
 FROM sysibmadm.mon_current_sql
 ORDER BY elapsed_time_sec DESC`;
  }
};

// src/service/main/dialect/dorisDialect.ts
var g2 = class extends bd {
  tableTemplate() {
    return `CREATE TABLE table_name(  
    id int NOT NULL  COMMENT 'Primary Key',
    create_time DATETIME COMMENT 'Create Time',
    name VARCHAR(255)
) 
AGGREGATE KEY(id,create_time,name)
DISTRIBUTED BY HASH(id) BUCKETS 1
PROPERTIES (
    "replication_allocation" = "tag.location.default: 1"
);`;
  }
  showColumns(e, t) {
    return `SELECT 
        c.COLUMN_NAME name,
        COLUMN_TYPE type,
        COLUMN_COMMENT comment,COLUMN_KEY \`key\`,IS_NULLABLE nullable,
        CHARACTER_MAXIMUM_LENGTH maximum_length,
        COLUMN_DEFAULT defaultValue,
        INSTR(COLUMN_TYPE,'zerofill')>0 "zerofill",
        INSTR(COLUMN_TYPE,'unsigned')>0 "unsigned",
        EXTRA extra,
        COLLATION_NAME collation_name,
        CHARACTER_SET_NAME character_set_name 
        FROM information_schema.columns c
        WHERE c.table_schema = '${e}' AND c.table_name = '${t}' 
        ORDER BY c.ORDINAL_POSITION;`;
  }
};

// src/service/main/dialect/sql-other/tdEngineDialect.ts
var _2 = class extends os {
  showVersion() {
    return "SELECT SERVER_VERSION();";
  }
  createIndex(e) {
    let t = `${e.type || "key"}`;
    return t.match(/BTREE/i) && (t = "key"), `ALTER TABLE ${e.table} ADD ${t} (\`${e.column || "$1"}\`)`;
  }
  dropIndex(e, t) {
    return `ALTER TABLE ${e} DROP INDEX \`${t}\``;
  }
  showIndex(e, t) {
    return `SELECT column_name "column_name",index_name "index_name",index_type "index_type",non_unique=0 "isUnique" FROM INFORMATION_SCHEMA.STATISTICS WHERE table_schema='${e}' and table_name='${t}';`;
  }
  addColumn(e, t) {
    let n = t ? ` AFTER \`${t}\`` : "";
    return `ALTER TABLE ${e} 
    ADD COLUMN $1 [type]$2 COMMENT '$3'${n};`;
  }
  createUser() {
    return `CREATE USER '$1'@'%' IDENTIFIED BY 'password$2';
-- Grant select privilege to all databases;
GRANT SELECT ON *.* TO '$1'@'%' WITH GRANT OPTION;
-- Grant all privileges to all databases;
GRANT ALL PRIVILEGES ON *.* TO '$1'@'%' WITH GRANT OPTION;`;
  }
  updateUser(e) {
    return `update mysql.user set 
    password = PASSWORD("newPassword")
    where User = '${e}';
FLUSH PRIVILEGES;
-- since mysql version 5.7, password column need change to authentication_string=PASSWORD("newPassword")`;
  }
  updateColumn(e, t) {
    let { nullable: n, extra: s } = t;
    return this.updateColumnSql({
      table: e,
      ...t,
      isNotNull: n != "YES",
      isAutoIncrement: s?.toLowerCase()?.includes?.("auto_increment")
    });
  }
  updateColumnSql(e) {
    let {
      table: t,
      name: n,
      columnName: s = n,
      type: o,
      unsigned: a,
      zerofill: c,
      useCurrentTimestamp: u,
      isNotNull: l,
      isAutoIncrement: f,
      comment: h,
      defaultValue: p,
      character_set_name: m,
      collation_name: E
    } = e, g = !Al(o) && !o?.match(/json/i);
    return new lt(`ALTER TABLE \`${t}\``).append(`
	CHANGE \`${s}\` \`${n}\` ${o}`).if(a == "1", "UNSIGNED").if(c == "1", "ZEROFILL").if(u, "ON UPDATE CURRENT_TIMESTAMP").if(g && m, `CHARACTER SET ${m}`).if(g && E, `COLLATE ${E}`).if(l, "NOT NULL").if(f, "AUTO_INCREMENT").if(h, `COMMENT '${h}'`).if(ac(p) && !l, "DEFAULT NULL").if(!ac(p), `DEFAULT ${p == "CURRENT_TIMESTAMP" ? p : `${Aa(p, o)}`}`).append(";").toString();
  }
  showCollations() {
    return null;
  }
  pingDataBase(e) {
    return e ? `use \`${e}\`` : null;
  }
  updateTable(e) {
    let { table: t, newTableName: n, comment: s, newComment: o, collation: a, newCollation: c } = e, u = "";
    return o && o != s && (u = `ALTER TABLE \`${t}\` COMMENT = '${o}';`), c && c != a && (u += `ALTER TABLE \`${t}\` collate = '${c}';`), n && t != n && (u += `ALTER TABLE \`${t}\` RENAME TO \`${n}\`;`), u;
  }
  truncateDatabase(e) {
    return `SELECT Concat('TRUNCATE TABLE \`',table_schema,'\`.\`',TABLE_NAME, '\`;') trun FROM INFORMATION_SCHEMA.TABLES where  table_schema ='${e}' and TABLE_TYPE<>'VIEW';`;
  }
  createDatabase(e) {
    return "CREATE DATABASE $1;";
  }
  showTableSource(e, t) {
    return `SHOW CREATE TABLE \`${e}\`.\`${t}\`;`;
  }
  /**
   * https://dev.mysql.com/doc/refman/5.7/en/partitioning-management-range-list.html
   */
  showPartitions(e, t) {
    return `SELECT 
PARTITION_NAME "name",PARTITION_METHOD "strategy",PARTITION_EXPRESSION "columnName",
PARTITION_DESCRIPTION "value",TABLE_ROWS "rows",DATA_LENGTH "length"
        FROM information_schema.partitions WHERE TABLE_SCHEMA='${e}' AND TABLE_NAME = '${t}' AND PARTITION_NAME IS NOT NULL`;
  }
  showViewSource(e, t) {
    return `SHOW CREATE VIEW  \`${e}\`.\`${t}\`;`;
  }
  showTriggerSource(e, t) {
    return `SHOW CREATE TRIGGER \`${e}\`.\`${t}\`;`;
  }
  showColumns(e, t) {
    return `desc ${t}`;
  }
  showForeignKeys(e, t) {
    return `SELECT
        c.COLUMN_NAME column_name, ik.CONSTRAINT_NAME constraint_name,
        ik.REFERENCED_TABLE_NAME referenced_table, ik.REFERENCED_COLUMN_NAME referenced_column,
        UPDATE_RULE "updateRule",
        DELETE_RULE "deleteRule"
        FROM
        information_schema.columns c join information_schema.KEY_COLUMN_USAGE ik on c.table_schema = ik.TABLE_SCHEMA
        and c.table_name = ik.TABLE_NAME and c.COLUMN_NAME = ik.COLUMN_NAME
        JOIN information_schema.REFERENTIAL_CONSTRAINTS ir on ik.CONSTRAINT_NAME=ir.CONSTRAINT_NAME
        WHERE c.table_schema = '${e}' and c.table_name = '${t}' ORDER BY ik.CONSTRAINT_NAME;`;
  }
  showViews(e) {
    return `SELECT TABLE_NAME name,SECURITY_TYPE "view_group" FROM information_schema.VIEWS  WHERE TABLE_SCHEMA = '${e}' ORDER BY TABLE_NAME`;
  }
  buildPageSql(e, t, n) {
    return `SELECT * FROM ${t} LIMIT ${n};`;
  }
  showTables(e) {
    return `show ${e}.tables;`;
  }
  showDatabases() {
    return "show databases";
  }
  showSchemas() {
    return this.showDatabases();
  }
  tableTemplate(e) {
    return `CREATE TABLE table_name$1(  
    create_time timestamp,
    name$2 NCHAR(255)
);`;
  }
  viewTemplate() {
    return `CREATE VIEW view_name$1
AS
SELECT * FROM $2`;
  }
  procedureTemplate() {
    return `CREATE PROCEDURE proc_name$1()
BEGIN
$2
END;`;
  }
  functionTemplate() {
    return `CREATE FUNCTION fun_name$1() RETURNS int$2
READS SQL DATA
BEGIN
    $3
    return 0;
END;`;
  }
};

