// src/bin/sql-formatter/languages/hive/hive.formatter.ts
var xOt = $e(["SELECT [ALL | DISTINCT]"]), DOt = $e([
  // queries
  "WITH",
  "FROM",
  "WHERE",
  "GROUP BY",
  "HAVING",
  "WINDOW",
  "PARTITION BY",
  "ORDER BY",
  "SORT BY",
  "CLUSTER BY",
  "DISTRIBUTE BY",
  "LIMIT",
  // Data manipulation
  // - insert:
  //   Hive does not actually support plain INSERT INTO, only INSERT INTO TABLE
  //   but it's a nuisance to not support it, as all other dialects do.
  "INSERT INTO [TABLE]",
  "VALUES",
  // - update:
  "SET",
  // - merge:
  "MERGE INTO",
  "WHEN [NOT] MATCHED [THEN]",
  "UPDATE SET",
  "INSERT [VALUES]",
  // - insert overwrite directory:
  //   https://cwiki.apache.org/confluence/display/Hive/LanguageManual+DML#LanguageManualDML-Writingdataintothefilesystemfromqueries
  "INSERT OVERWRITE [LOCAL] DIRECTORY",
  // - load:
  //   https://cwiki.apache.org/confluence/display/Hive/LanguageManual+DML#LanguageManualDML-Loadingfilesintotables
  "LOAD DATA [LOCAL] INPATH",
  "[OVERWRITE] INTO TABLE"
]), uNe = $e([
  // - create:
  "CREATE [TEMPORARY] [EXTERNAL] TABLE [IF NOT EXISTS]",
  "CREATE [MATERIALIZED] VIEW [IF NOT EXISTS]",
  // - update:
  "UPDATE",
  // - delete:
  "DELETE FROM",
  // - drop table:
  "DROP TABLE [IF EXISTS]",
  // - alter table:
  "ALTER TABLE",
  "RENAME TO",
  // - truncate:
  "TRUNCATE [TABLE]",
  // other
  "ALTER",
  "CREATE",
  "USE",
  "DESCRIBE",
  "DROP",
  "FETCH",
  "SHOW",
  "STORED AS",
  "STORED BY",
  "ROW FORMAT"
]), LOt = $e(["UNION [ALL | DISTINCT]"]), vOt = $e([
  "JOIN",
  "{LEFT | RIGHT | FULL} [OUTER] JOIN",
  "{INNER | CROSS} JOIN",
  // non-standard joins
  "LEFT SEMI JOIN"
]), POt = $e(["{ROWS | RANGE} BETWEEN"]), EQ = {
  name: "hive",
  tokenizerOptions: {
    reservedSelect: xOt,
    reservedClauses: [...DOt, ...uNe],
    reservedSetOperations: LOt,
    reservedJoins: vOt,
    reservedPhrases: POt,
    reservedKeywords: aNe,
    reservedDataTypes: cNe,
    reservedFunctionNames: oNe,
    extraParens: ["[]"],
    stringTypes: ['""-bs', "''-bs"],
    identTypes: ["``"],
    variableTypes: [{ quote: "{}", prefixes: ["$"], requirePrefix: !0 }],
    operators: ["%", "~", "^", "|", "&", "<=>", "==", "!", "||"]
  },
  formatOptions: {
    onelineClauses: uNe
  }
};

// src/bin/sql-formatter/languages/mariadb/likeMariaDb.ts
function nR(r) {
  return r.map((e, t) => {
    let n = r[t + 1] || Md;
    if (Df.SET(e) && n.text === "(")
      return { ...e, type: "RESERVED_FUNCTION_NAME" };
    let s = r[t - 1] || Md;
    return Df.VALUES(e) && s.text === "=" ? { ...e, type: "RESERVED_FUNCTION_NAME" } : e;
  });
}

